mapper.select:
SELECT * FROM ai_conversation
WHERE user_id = #{userId} AND state = #{state}
ORDER BY updated_at DESC, id DESC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE ai_conversation
SET title = #{title}, updated_at = #{updatedAt}, version = version + 1
WHERE id = #{id} AND user_id = #{userId} AND state = 'ACTIVE' AND version = #{version}

UPDATE ai_conversation
SET state = 'DELETED', deleted_at = #{deletedAt}, updated_at = #{updatedAt}, version = version + 1
WHERE id = #{id} AND user_id = #{userId} AND state = 'ACTIVE' AND version = #{version}
